function validateCursor(raw: unknown): SessionCursor | undefined {
  if (typeof raw !== 'object' || raw === null) return undefined;
  const {updatedAt, sessionId} = raw as Record<string, unknown>;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH) return undefined;
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return undefined;
  if (!Number.isFinite(new Date(updatedAt).getTime())) return undefined;
  return {updatedAt, sessionId};
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const data: ListSessionsMessage = {type: 'list_sessions'};

  if (message.limit !== undefined) {
    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
    }
    data.limit = message.limit;
  }

  if (message.before !== undefined) {
    const before = validateCursor(message.before);
    if (!before) {
      return {valid: false, error: 'list_sessions before must be a cursor with a sessionId and a valid updatedAt'};
    }
    data.before = before;
  }

  return {valid: true, data};
}
'''
